begin;
create temporary table bill_ids(label text primary key,id uuid default gen_random_uuid());insert into bill_ids(label) values('alice'),('bob');grant select on bill_ids to authenticated;
insert into auth.users(id) select id from bill_ids;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from bill_ids where label='alice'),true);
do $$
declare c public.categories%rowtype;r public.recurring_rules%rowtype;v text;bill uuid;fav uuid;tx uuid;prior uuid;before_s jsonb;s jsonb;p jsonb;k uuid:=gen_random_uuid();today date:=timezone('Asia/Bangkok',now())::date;m date:=date_trunc('month',timezone('Asia/Bangkok',now()))::date;
begin
 perform public.complete_onboarding('Bill Alice','เงินรวม',10000);
 select * into c from public.categories where owner_id=auth.uid() order by created_at,id limit 1;
 before_s:=public.moneyspace_snapshot(m);
 bill:=(public.moneyspace_write('create_bill',jsonb_build_object('name','Phone','amount','500.25','category_id',c.id,'first_month',m,'due_day',31),gen_random_uuid())->>'id')::uuid;
 fav:=(public.moneyspace_write('create_template',jsonb_build_object('name','Coffee','amount','50.50','category_id',c.id),gen_random_uuid())->>'id')::uuid;
 s:=public.moneyspace_snapshot(m);
 if s->>'cash'<>before_s->>'cash' or s->>'expenses'<>before_s->>'expenses' or s->>'savings'<>before_s->>'savings' or s->>'transaction_count'<>before_s->>'transaction_count' then raise exception 'FAIL: bill/template definitions changed money';end if;
 if (s->'bills'->>'pending_total')::numeric<>500.25 or jsonb_array_length(s->'expense_templates')<>1 then raise exception 'FAIL: missing bill/template';end if;
 if moneyspace_private.bill_due('2028-02-01',31)<>'2028-02-29'::date or moneyspace_private.bill_due('2026-02-01',31)<>'2026-02-28'::date then raise exception 'FAIL: month clamp';end if;
 select * into r from public.recurring_rules where id=bill;
 p:=jsonb_build_object('id',bill,'version',r.updated_at,'month',m,'amount','499.99','date',today);
 tx:=(public.moneyspace_write('pay_bill',p,k)->>'id')::uuid;
 perform public.moneyspace_write('pay_bill',p,k);
 s:=public.moneyspace_snapshot(m);
 if (s->>'cash')::numeric<>9500.01 or (s->>'expenses')::numeric<>499.99 or (s->'bills'->>'pending_total')::numeric<>0 or (s->>'transaction_count')::integer<>1 then raise exception 'FAIL: pay duplicated or estimate deducted: %',s;end if;
 begin perform public.moneyspace_write('pay_bill',p,gen_random_uuid());raise exception 'FAIL: duplicate period';exception when raise_exception then if sqlerrm<>'BILL_ALREADY_PAID' then raise;end if;end;
 select * into r from public.recurring_rules where id=bill;
 perform public.moneyspace_write('update_bill',jsonb_build_object('id',bill,'version',r.updated_at,'name','Renamed','amount','600','category_id',c.id,'first_month',m,'due_day',1),gen_random_uuid());
 s:=public.moneyspace_snapshot(m);
 if s->'bills'->'items'->0->>'name'<>'Phone' or (s->'bills'->>'pending_total')::numeric<>0 then raise exception 'FAIL: definition update changed paid history or reopened period';end if;
 select updated_at::text into v from public.transactions where id=tx;
 perform public.moneyspace_write('delete_transaction',jsonb_build_object('id',tx,'version',v),gen_random_uuid());
 s:=public.moneyspace_snapshot(m);
 if (s->>'cash')::numeric<>10000 or (s->'bills'->>'pending_total')::numeric<>600 then raise exception 'FAIL: deleted expense did not reopen bill';end if;
 prior:=(public.moneyspace_write('add_transaction',jsonb_build_object('kind','expense','amount','588.88','category_id',c.id,'date',today),gen_random_uuid())->>'id')::uuid;
 select * into r from public.recurring_rules where id=bill;
 if jsonb_array_length(public.moneyspace_bill_candidates(bill,m))<>1 then raise exception 'FAIL: existing candidate missing';end if;
 perform public.moneyspace_write('pay_bill',jsonb_build_object('id',bill,'version',r.updated_at,'month',m,'transaction_id',prior,'transaction_version',(select updated_at from public.transactions where id=prior)),gen_random_uuid());
 s:=public.moneyspace_snapshot(m);
 if (s->>'cash')::numeric<>9411.12 or (s->>'expenses')::numeric<>588.88 or (s->>'transaction_count')::integer<>1 or (s->'bills'->>'pending_total')::numeric<>0 then raise exception 'FAIL: linking double counted';end if;
 select * into r from public.recurring_rules where id=bill;
 begin perform public.moneyspace_write('update_bill',jsonb_build_object('id',bill,'version','2000-01-01','name','stale','amount','1','category_id',c.id,'first_month',m,'due_day',1),gen_random_uuid());raise exception 'FAIL: stale accepted';exception when raise_exception then if sqlerrm<>'STALE_VERSION' then raise;end if;end;
 perform public.moneyspace_write('stop_bill',jsonb_build_object('id',bill,'version',r.updated_at),gen_random_uuid());
 s:=public.moneyspace_snapshot(m);
 if jsonb_array_length(s->'bills'->'rules')<>0 or jsonb_array_length(s->'bills'->'items')<>1 or s->'bills'->'items'->0->>'name'<>'Renamed' then raise exception 'FAIL: stopping lost paid history';end if;
 select updated_at::text into v from public.expense_templates where id=fav;
 perform public.moneyspace_write('update_template',jsonb_build_object('id',fav,'version',v,'name','Lunch','amount','60','category_id',c.id),gen_random_uuid());
 select updated_at::text into v from public.expense_templates where id=fav;
 perform public.moneyspace_write('delete_template',jsonb_build_object('id',fav,'version',v),gen_random_uuid());
 if jsonb_array_length(public.moneyspace_snapshot(m)->'expense_templates')<>0 then raise exception 'FAIL: deleted template shown';end if;
 begin insert into public.expense_templates(owner_id,name,amount,category_id) values(auth.uid(),'Bypass',1,c.id);raise exception 'FAIL: direct insert';exception when insufficient_privilege then null;end;
 begin update public.recurring_rules set amount=1 where id=bill;raise exception 'FAIL: direct rule update';exception when insufficient_privilege then null;end;
 begin update public.bill_payments set voided_at=now() where owner_id=auth.uid();raise exception 'FAIL: direct payment mutation';exception when insufficient_privilege then null;end;
 begin perform moneyspace_private.bill_action('stop_bill',jsonb_build_object('id',bill));raise exception 'FAIL: private bypass';exception when insufficient_privilege then null;end;
 begin perform public.moneyspace_write('create_template',jsonb_build_object('name','Bad','amount','0','category_id',c.id),gen_random_uuid());raise exception 'FAIL: zero accepted';exception when raise_exception then if sqlerrm<>'INVALID_BILL_TEMPLATE' then raise;end if;end;
end $$;
do $$
declare c uuid;bill uuid;r public.recurring_rules%rowtype;m date:=date_trunc('month',timezone('Asia/Bangkok',now()))::date;prior_month date:=(date_trunc('month',timezone('Asia/Bangkok',now()))-interval '1 month')::date;s jsonb;tx uuid;
begin
 select id into c from public.categories where owner_id=auth.uid() order by created_at,id limit 1;
 bill:=(public.moneyspace_write('create_bill',jsonb_build_object('name','Arrears','amount','100','category_id',c,'first_month',prior_month,'due_day',31),gen_random_uuid())->>'id')::uuid;
 s:=public.moneyspace_snapshot(m);
 if (s->'bills'->>'pending_total')::numeric<>200 or jsonb_array_length(s->'bills'->'pending_current')<>2 then raise exception 'FAIL: missed arrears';end if;
 if jsonb_array_length(public.moneyspace_snapshot(prior_month)->'bills'->'items')<>1 then raise exception 'FAIL: wrong historical bill items';end if;
 perform public.moneyspace_write('create_bill',jsonb_build_object('name','Future','amount','999','category_id',c,'first_month',(m+interval '1 month')::date,'due_day',1),gen_random_uuid());
 if (public.moneyspace_snapshot(m)->'bills'->>'pending_total')::numeric<>200 then raise exception 'FAIL: future bill included early';end if;
 -- An old expense is linkable even after falling beyond the 100-entry preview.
 tx:=(public.moneyspace_write('add_transaction',jsonb_build_object('kind','expense','amount','90','category_id',c,'date',prior_month),gen_random_uuid())->>'id')::uuid;
 for i in 1..101 loop perform public.moneyspace_write('add_transaction',jsonb_build_object('kind','expense','amount','1','category_id',c,'date',timezone('Asia/Bangkok',now())::date),gen_random_uuid());end loop;
 select * into r from public.recurring_rules where id=bill;
 begin perform public.moneyspace_write('pay_bill',jsonb_build_object('id',bill,'version',r.updated_at,'month',prior_month,'transaction_id',tx,'transaction_version','2000-01-01'),gen_random_uuid());raise exception 'FAIL: stale linked expense';exception when raise_exception then if sqlerrm<>'STALE_VERSION' then raise;end if;end;
 perform public.moneyspace_write('pay_bill',jsonb_build_object('id',bill,'version',r.updated_at,'month',prior_month,'transaction_id',tx,'transaction_version',(select updated_at from public.transactions where id=tx)),gen_random_uuid());
 s:=public.moneyspace_snapshot(prior_month);
 if s->'bills'->'items'->0->'transaction'->>'id'<>tx::text or (s->'bills'->>'pending_total')::numeric<>100 then raise exception 'FAIL: historical paid entry unavailable or arrears still pending';end if;
end $$;
reset role;
create temporary table foreign_bill as select id,updated_at from public.recurring_rules where owner_id=(select id from bill_ids where label='alice');grant select on foreign_bill to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from bill_ids where label='bob'),true);
do $$declare s jsonb;r record;begin
 perform public.complete_onboarding('Bill Bob','เงินรวม',0);
 s:=public.moneyspace_snapshot(date_trunc('month',timezone('Asia/Bangkok',now()))::date);
 if (s->'bills'->>'pending_total')::numeric<>0 or jsonb_array_length(s->'expense_templates')<>0 or exists(select 1 from public.bill_payments) or exists(select 1 from public.expense_templates) then raise exception 'FAIL: foreign data exposed';end if;
 select * into r from foreign_bill;
 begin perform public.moneyspace_bill_candidates(r.id,date_trunc('month',current_date)::date);raise exception 'FAIL: foreign candidates';exception when insufficient_privilege then null;end;
 begin perform public.moneyspace_write('stop_bill',jsonb_build_object('id',r.id,'version',r.updated_at),gen_random_uuid());raise exception 'FAIL: foreign edit';exception when insufficient_privilege then null;end;
end $$;
reset role;set local role anon;
do $$begin
 begin perform public.moneyspace_bill_status(current_date);raise exception 'FAIL: anon status';exception when insufficient_privilege then null;end;
 begin select 1 from public.expense_templates;raise exception 'FAIL: anon templates';exception when insufficient_privilege then null;end;
end $$;
reset role;
rollback;
